layer.css:
[data-ryt="pitch"] { color: var(--ryt-text); border-left: 8px solid rgb(224, 224, 224); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 17.3333px; font-weight: 300; font-style: italic; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 17.3333px; padding-right: 0px; padding-bottom: 17.3333px; padding-left: 34.6667px; transition: all; border-top: none; border-right: none; border-bottom: none }
article[data-ryt="rec-card"] { border-bottom: 1px dotted var(--ryt-text); border-radius: 0px; transition: color 0.2s ease-in-out, border-color 0.2s ease-in-out, opacity 0.2s ease-in-out; border-top: none; border-right: none; border-left: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: #3d90b3; border-bottom: 1px dotted rgb(55, 192, 251); border-radius: 0px; font-weight: 300; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(55, 192, 251); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.2s ease-in-out, border-color 0.2s ease-in-out, opacity 0.2s ease-in-out; border-top: none; border-right: none; border-left: none }
[data-ryt="hero"] h1 { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 30.3333px; font-weight: 600; font-style: normal; line-height: 1.75; letter-spacing: -0.758333px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="section"] > h2 { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 600; font-style: normal; line-height: 1.75; letter-spacing: -0.758333px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="review"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 17.3333px; font-weight: 300; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 300; font-style: normal; line-height: 1.625; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-bottom: 1px dotted var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 600; font-style: normal; letter-spacing: -0.52px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.2s ease-in-out, border-color 0.2s ease-in-out, opacity 0.2s ease-in-out; border-top: none; border-right: none; border-left: none }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 26px; font-weight: 600; font-style: normal; line-height: 1.167; letter-spacing: -0.65px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.2s ease-in-out, border-color 0.2s ease-in-out, opacity 0.2s ease-in-out }
[data-ryt="header"] { background-image: url("{{assets}}/hugo-arcana_20ee7d0ada2c/bg02.png"), url("{{assets}}/hugo-arcana_20ee7d0ada2c/bg02.png"), url("{{assets}}/hugo-arcana_20ee7d0ada2c/bg01.png"); background-size: 100% 104px, 100% 104px, auto; background-position: 0% 0%, 0% 0%, 0% 0%; background-repeat: no-repeat, no-repeat, repeat }
[data-ryt="nav"] a { color: #909090; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 17.3333px; font-weight: 300; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(192, 192, 192); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 26px; padding-right: 8.66667px; padding-bottom: 23.4px; padding-left: 8.66667px; transition: color 0.2s ease-in-out, border-color 0.2s ease-in-out, opacity 0.2s ease-in-out }
body { background-image: url("{{assets}}/hugo-arcana_20ee7d0ada2c/bg01.png"); background-size: auto; background-position: 0% 0%; background-repeat: repeat }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 20.8px; font-weight: 600; font-style: normal; line-height: 1.75; letter-spacing: -0.52px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a:hover { border-bottom-color: transparent }
[data-ryt="brand"]:hover { border-bottom-color: transparent }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { border-bottom-color: transparent }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { border-bottom-color: transparent }
article[data-ryt="rec-card"]:hover { color: rgb(55, 192, 251); border-bottom-color: transparent }
